      "Ọgbọ ga-eto ọrụ Gị nye ọgbọ ọzọ, ga-akọkwa ọrụ ike Gị.",
      "Aga m ekwu banyere nsọpụrụ ebube nke ịdị ukwuu Gị, na banyere ọrụ ebube Gị.",
