      "Ha ga-ekwu maka ebube nke alaeze Gị, kwuo banyere ike Gị;",
      "Iji mee ka ụmụ mmadụ mara ọrụ ike Gị, na ebube nke ịdị ukwuu alaeze Gị.",
      "Alaeze Gị bụ alaeze ebighị ebi; ọchịchị Gị na-adịru n’ọgbọ niile."
