      "Otu a kwa, Mmụọ Nsọ na-enyere adịghị ike anyị aka; n’ihi na anyị amaghị ihe anyị kwesịrị ịrịọ dịka kwesịrị; ma Mmụọ n’onwe Ya na-arịọ arịrịọ n’ihi anyị site n’ịkwa ákwá na-enweghị okwu.",
