      "Ndị O họpụtara, ndị ahụ ka O kpọrọ; ndị O kpọrọ, ndị ahụ ka O gụrụ n’ezi omume; ndị O gụrụ n’ezi omume, ndị ahụ ka O nyere ebube.",
