      "Mgbe anyị anaghị ele ihe a na-ahụ anya, kama ihe a na-adịghị ahụ anya: n’ihi na ihe a na-ahụ anya bụ nke oge, ma ihe a na-adịghị ahụ anya bụ nke ebighị ebi."
